<?php header("Content-Type: application/json; charset=UTF-8"); require_once "db.php"; try { if ($_SERVER["REQUEST_METHOD"] !== "POST") { throw new Exception("Invalid request method."); } $donation_id = intval($_POST["donation_id"] ?? 0); $user_id = intval($_POST["user_id"] ?? 0); if ($donation_id <= 0 || $user_id <= 0) { throw new Exception("Invalid donation or user."); } /* * Make sure the donation belongs to this donor. */ $checkSql = " SELECT donation_id FROM food_donations WHERE donation_id = ? AND user_id = ? LIMIT 1 "; $check = $conn->prepare($checkSql); $check->bind_param("ii", $donation_id, $user_id); $check->execute(); $result = $check->get_result(); if ($result->num_rows === 0) { throw new Exception("Donation not found."); } $check->close(); /* * Delete the claim records first. * * This avoids problems if a foreign key exists. */ $claimSql = " DELETE FROM food_claims WHERE donation_id = ? "; $claimStmt = $conn->prepare($claimSql); $claimStmt->bind_param("i", $donation_id); $claimStmt->execute(); $claimStmt->close(); /* * Delete the donation. */ $deleteSql = " DELETE FROM food_donations WHERE donation_id = ? AND user_id = ? "; $stmt = $conn->prepare($deleteSql); $stmt->bind_param("ii", $donation_id, $user_id); if (!$stmt->execute()) { throw new Exception("Unable to delete donation."); } $stmt->close(); $conn->close(); echo json_encode([ "success" => true, "message" => "Food donation deleted successfully." ]); } catch (Throwable $e) { http_response_code(500); echo json_encode([ "success" => false, "message" => $e->getMessage() ]); } ?>